ruleToc.nextTocUrl:
text.下一页@href
@js:
var regex=/第\d*.(\d+)页.当前\d*条.页/;
//正则匹配页数
var page=src.match(regex);
page=page?page[1]:"";
var next=result?result[0]:"";
next=String(next);
var url=[next];
for(i=2;i<=page;i++){
	url.push(next.replace(/_\d+/,"_"+i))
	}
url;

ruleContent.content:
@js:
content = org.jsoup.Jsoup.parse(src).select(".word_read > script")
let context= "";
content.forEach(i => {
	i = i.data().match(/'(.+)'/)[1];
	context += java.base64Decode(i) + "\n"
	})
context

